/**
 * Custom Worker entrypoint wrapping the OpenNext-generated handler.
 *
 * Adds Cloudflare request geolocation as the headers umami already understands
 * (src/lib/detect.ts reads cf-ipcountry / cf-region-code / cf-ipcity), so no
 * MaxMind database is needed.
 */
// @ts-expect-error generated by `opennextjs-cloudflare build`
import { default as handler } from '../../.open-next/worker.js';

type IncomingCf = {
  country?: string;
  city?: string;
  regionCode?: string;
  region?: string;
};

/** Headers are byte strings: encode UTF-8 as latin1 (umami decodes it back). */
function toHeaderValue(value: string): string {
  return Buffer.from(value, 'utf8').toString('latin1');
}

function withGeoHeaders(request: Request): Request {
  const cf = (request as Request & { cf?: IncomingCf }).cf;

  if (!cf) {
    return request;
  }

  const headers = new Headers(request.headers);
  let changed = false;

  const set = (name: string, value?: string) => {
    if (value && !headers.has(name)) {
      headers.set(name, toHeaderValue(value));
      changed = true;
    }
  };

  set('cf-ipcountry', cf.country);
  set('cf-region-code', cf.regionCode);
  set('cf-ipcity', cf.city);

  return changed ? new Request(request, { headers }) : request;
}

export default {
  async fetch(request: Request, env: unknown, ctx: ExecutionContext): Promise<Response> {
    return handler.fetch(withGeoHeaders(request), env, ctx);
  },
} satisfies ExportedHandler;
